const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const lakeSambhar = ee.Geometry.Point([75.1, 26.9]).buffer(15000); // 15km buffer around lake center

  const date2018Start = '2018-01-01';
  const date2018End = '2018-12-31';
  const date2019Start = '2019-01-01';
  const date2019End = '2019-12-31';

  // Cloud masking function
  function maskClouds(image) {
    const qa = image.select('QA60');
    const cloudBit = 1 << 10;
    const cirrusBit = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBit).eq(0)
                   .and(qa.bitwiseAnd(cirrusBit).eq(0));
    return image.updateMask(mask);
  }

  // Water detection function using MNDWI
  function addMNDWI(image) {
    const mndwi = image.normalizedDifference(['B3', 'B11']).rename('MNDWI');
    return image.addBands(mndwi);
  }

  // 2. Data Acquisition & Check
  let col2018 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lakeSambhar)
    .filterDate(date2018Start, date2018End)
    .map(maskClouds)
    .map(addMNDWI);

  let col2019 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(lakeSambhar)
    .filterDate(date2019Start, date2019End)
    .map(maskClouds)
    .map(addMNDWI);

  const size2018 = await col2018.size().getInfo();
  const size2019 = await col2019.size().getInfo();

  console.log(`2018 Images: ${size2018}`);
  console.log(`2019 Images: ${size2019}`);

  if (size2018 === 0 || size2019 === 0) {
    console.log("Insufficient data for one or both years.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create median composites
  const composite2018 = col2018.median();
  const composite2019 = col2019.median();

  // Identify water pixels (MNDWI > 0)
  const water2018 = composite2018.select('MNDWI').gt(0);
  const water2019 = composite2019.select('MNDWI').gt(0);

  // 4. Calculate water extent (pixel count)
  const stats2018 = await water2018.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeSambhar,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const stats2019 = await water2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeSambhar,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const waterPixels2018 = stats2018.MNDWI;
  const waterPixels2019 = stats2019.MNDWI;

  console.log(`2018 Water Pixels: ${waterPixels2018}`);
  console.log(`2019 Water Pixels: ${waterPixels2019}`);

  // 5. Validation & Final Answer
  if (waterPixels2018 === null || waterPixels2019 === null || 
      waterPixels2018 === undefined || waterPixels2019 === undefined) {
    console.log("Calculation failed - null values.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (waterPixels2018 === 0 && waterPixels2019 === 0) {
    console.log("No valid water pixels detected in either year.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Compare water extent
  if (waterPixels2019 < waterPixels2018) {
    console.log("Water extent decreased from 2018 to 2019.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Water extent did not decrease from 2018 to 2019.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
